    this.files = [
      {
        label: "documents",
        data: "documents folder",
        expandedIcon: "pi pi-folder-open",
        collapsedIcon: "pi pi-folder",
        children: [
          {
            label: "work",
            data: "work folder",
            expandedIcon: "pi pi-folder-open",
            collapsedIcon: "pi pi-folder",
            children: [
              {
                label: "expenses.doc",
                icon: "pi pi-file",
                data: "expenses document",
              },
              {
                label: "resume.doc",
                icon: "pi pi-file",
                data: "resume document",
              },
            ],
          },
          {
            label: "home",
            data: "home folder",
            expandedIcon: "pi pi-folder-open",
            collapsedIcon: "pi pi-folder",
            children: [
              {
                label: "invoices.txt",
                icon: "pi pi-file",
                data: "invoices for this month",
              },
            ],
          },
        ],
      },
      {
        label: "pictures",
        data: "pictures folder",
        expandedIcon: "pi pi-folder-open",
        collapsedIcon: "pi pi-folder",
        children: [
