import { DOCUMENT } from "@angular/common";
import { FormsModule } from "@angular/forms";
import { ChangeDetectionStrategy, Component, inject } from "@angular/core";

import { TreeModule } from "primeng/tree";
import { MenuItem, TreeNode } from "primeng/api";
import { PaginatorModule } from "primeng/paginator";
import { BreadcrumbModule } from "primeng/breadcrumb";
import { InputSwitchModule } from "primeng/inputswitch";

import { BlockerLoaderComponent } from "../../../shared/components/blocker-loader/blocker-loader.component";
import { ButtonModule } from "primeng/button";

@Component({
  selector: "app-main-dashboard",
  standalone: true,
  imports: [
    FormsModule,
    TreeModule,
    ButtonModule,
    PaginatorModule,
    BreadcrumbModule,
    InputSwitchModule,
    BlockerLoaderComponent,
  ],
  templateUrl: "./main-dashboard.component.html",
  styleUrls: ["./main-dashboard.component.css"],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MainDashboardComponent {
  files: TreeNode[] = [];
  lastNode: TreeNode | undefined;

  ngOnInit() {
    this.files = [
      {
        label: "documents",
        data: "documents folder",
        expandedIcon: "pi pi-folder-open",
        collapsedIcon: "pi pi-folder",
        children: [
          {
            label: "work",
            data: "work folder",
            expandedIcon: "pi pi-folder-open",
            collapsedIcon: "pi pi-folder",
            children: [
              {
                label: "expenses.doc",
                icon: "pi pi-file",
                data: "expenses document",
              },
              {
                label: "resume.doc",
                icon: "pi pi-file",
                data: "resume document",
              },
            ],
          },
          {
            label: "home",
            data: "home folder",
            expandedIcon: "pi pi-folder-open",
            collapsedIcon: "pi pi-folder",
            children: [
              {
                label: "invoices.txt",
                icon: "pi pi-file",
                data: "invoices for this month",
              },
            ],
          },
        ],
      },
      {
        label: "pictures",
        data: "pictures folder",
        expandedIcon: "pi pi-folder-open",
        collapsedIcon: "pi pi-folder",
        children: [
          {
            label: "barcelona.jpg",
            icon: "pi pi-image",
            data: "barcelona photo",
          },
          { label: "logo.jpg", icon: "pi pi-image", data: "primefaces logo" },
          { label: "primeui.png", icon: "pi pi-image", data: "primeui logo" },
        ],
      },
    ];

    this.addParentReferences(this.files);
    this.lastNode = this.findLastNode(this.files);
  }

  addParentReferences(nodes: TreeNode[], parent?: TreeNode) {
    nodes.forEach(node => {
      node.parent = parent;
      if (node.children) {
        this.addParentReferences(node.children, node);
      }
    });
  }

  findLastNode(nodes: TreeNode[]): TreeNode {
    let lastNode = nodes[nodes.length - 1];
    while (lastNode.children && lastNode.children.length > 0) {
      lastNode = lastNode.children[lastNode.children.length - 1];
    }
    console.log(lastNode);
    return lastNode;
  }

  onNodeSelect(event: any) {
    if (event.node === this.lastNode) {
      this.highlightParents(event.node);
    }
  }

  highlightParents(node: TreeNode) {
    let parent = node.parent;
    while (parent) {
      parent.styleClass = "highlight";
      parent = parent.parent;
    }
  }
}
